const r = await api.get("/mails", {});
const items = r.items || [];
const labels = [...new Set(items.map(m => m.label))];
const refund = items.filter(m => m.label === "환불" || m.label === "refund" || (m.label || "").toLowerCase().includes("refund") || (m.label || "").includes("환불"));
return { total: r.count, labels, refundCount: refund.length, refundMails: refund.map(m => ({ id: m.id, subject: m.subject, label: m.label, received_at: m.received_at })) };

